import os, re, json

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', '/tmp/empty'))
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rest = t[m.end():].split('\n')[:h]
        rows = [r.split() for r in rest] if rest else []
        grid = [[int(x) for x in r] for r in rows]
        if k not in G and grid and all(0 <= x <= 9 for row in grid for x in row):
            G[k] = grid
    return G, t

G, log = load_grids()
print("Keys found:", list(G.keys()))

# Check if task-17ce086d exists
print("\n=== Checking for task-17ce086d in demos ===")
if 'task-17ce086d' in G:
    print("Demo exists!")
    print(G['task-17ce086d'])
else:
    print("No demo yet for task-17ce086d")

# Check previous sessions for this task
