            ]
        }
    ]
}

input_np = np.array(demo_data["task-17ce086d"][0]["input"])
output_np = np.array(demo_data["task-17ce086d"][0]["output"])

unchanged_1 = (output_np == 1) & (input_np == 1)
changed_to_3 = (output_np == 3) & (input_np == 1)

# New hypothesis: maybe it's about which 1s are "exposed" vs "shielded"
# Let me compute for each cell: 9s in Moore neighborhood (8 directions)
# and see if shielded cells stay 1

shield8 = np.zeros((8, 15), dtype=int)
for r in range(8):
    for c in range(15):
        if input_np[r, c] == 1:
            count = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 15:
                        if input_np[nr, nc] == 9:
                            count += 1
            shield8[r, c] = count

print("Shield8 (8-neighbor 9 count) for changed 3s:", np.min(shield8[changed_to_3]), "-", np.max(shield8[changed_to_3]))
print("Shield8 (8-neighbor 9 count) for unchanged 1s:", np.min(shield8[unchanged_1]), "-", np.max(shield8[unchanged_1]))

# Hmm, let me try something else: what if we look at 2D shapes?
# What if cells that are in "corner" configurations become 3?

# Let me check: for each 1, is there a 2x2 block that is all 1s or all 3s (in output)?

# Or maybe: look at the "convex hull" of 9s, and cells inside become 3

# Actually, let me try a much simpler approach
# What if: the "staying 1" cells are those that have a majority vote from neighbors?

# For each unchanged 1, check its 4 neighbors - do more stay 1 than that one?

neighbor_pattern = np.zeros((8, 15), dtype=int)
for r in range(8):
    for c in range(15):
        if input_np[r, c] == 1:
            same_type = 0
            diff_type = 0
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 15:
                        in_cell_1 = (input_np[nr, nc] == 1)
                        out_is_1 = (output_np[nr, nc] == 1)
                        if in_cell_1 == out_is_1:
                            same_type += 1
                        else:
                            diff_type += 1
            neighbor_pattern[r, c] = (same_type - diff_type)

print("\nNeighbor pattern for unchanged 1s:", np.min(neighbor_pattern[unchanged_1]), "-", np.max(neighbor_pattern[unchanged_1]))
print("Neighbor pattern for changed 3s:", np.min(neighbor_pattern[changed_to_3]), "-", np.max(neighbor_pattern[changed_to_3]))

# Maybe cells with positive neighbor pattern stay 1?

